using System;
using System.Collections;
using System.IO;
using System.Linq;
using EchoStation.Dialogue;
using EchoStation.Echo;
using EchoStation.Persistence;
using EchoStation.Player;
using EchoStation.Rendering;
using EchoStation.Station;
using EchoStation.Tests.Fixtures;
using EchoStation.World;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.TestTools;
namespace EchoStation.Tests.Station
{
 public sealed class StationPersistenceTests:StationPlayFixture
 {
  private string directory;
  private StationPersistence Store(){var p=station.GetComponent<StationPersistence>();Assert.That(p,Is.Not.Null);directory=Path.GetFullPath(Path.Combine("Library","EchoStation","S2WorldSaveTests",Guid.NewGuid().ToString("N")));p.ConfigureDirectory(directory);return p;}
  private IEnumerator Interact(string id,Vector3 point){Move(point);WorldTarget.Active.TryGet(id,out var target);Assert.That(target,Is.Not.Null,id);Look(target.transform.position);station.GetComponent<PlayerInputReader>().SetPointerCaptured(true);yield return Press(Key.E);}
  private IEnumerator UnlockCabin(){yield return Interact("cabin_terminal_01",new Vector3(-2.1f,.05f,.6f));var ui=station.GetComponent<StationTerminalPanel>();yield return Until(()=>ui.CodeInput.isFocused,5,"Code focus");foreach(var c in "7316")InputSystem.QueueTextEvent(inputs.Keyboard,c);yield return R04ShadowProbe.Frame();yield return Press(Key.Enter);Assert.That(station.Progress.Has("pz02"),Is.True);yield return Press(Key.Escape);yield return Interact("cabin_door_01",new Vector3(0,.05f,3.3f));Assert.That(WorldTarget.Active.TryGet("cabin_door_01",out var door)&&door.GetComponent<StationGate>().IsOpen,Is.True);}
  [UnityTest]public IEnumerator F03_C01_ActualReadScanSaveResetAndLoadRestoresHiddenFactsHistoryAndActorsOnce()
  {
   yield return new EnterPlayMode();yield return Boot();var persistence=Store();var fresh=persistence.Capture();WorldTarget.Active.TryGet("note_maintenance_01",out var note);yield return Interact(note.Id,note.GetComponent<EchoTargetPermissions>().ApproachPoint.position+Vector3.up*.05f);
   Assert.That(station.Journal.Store.TryGet("note_maintenance_01",out _),Is.True);Move(new Vector3(7.7f,.05f,1));station.Echo.GetComponent<EchoNavigation>().TryBind(new Vector3(1.5f,0,-2));station.Echo.TrySubmit(ScriptCommands.Investigate("scan_mark_01"),out _);yield return Until(()=>station.Echo.GetComponent<EchoScanController>().Scanner.Ledger.HasDiscovered("scan_mark_01"),18,"Actual cabin scan failed");Move(new Vector3(0,.05f,-2));station.Player.SetLookAngles(215,12);station.GetComponent<PlayerFlashlight>().SetOn(true);for(var i=0;i<60;i++)station.Dialogue.Session.TryAdd(DialogueSpeaker.Player,"历史夹具"+i,false,out _);var captured=persistence.Capture();var memory=captured.MemoryJson;Assert.That(persistence.TrySave(),Is.True,persistence.LastMessage);var disk=persistence.Files.Read();Assert.That(disk.Success,Is.True,disk.Detail);
   yield return persistence.RestoreData(fresh);Assert.That(persistence.LastSucceeded,Is.True,persistence.LastMessage);WorldTarget.Active.TryGet("scan_mark_01",out var hidden);Assert.That(hidden.GetComponent<ClueSource>().IsRevealed,Is.False);Assert.That(station.Memories.Store.Clues,Is.Empty);yield return persistence.Load();Assert.That(persistence.LastSucceeded,Is.True,persistence.LastMessage);Assert.That(hidden.GetComponent<ClueSource>().IsRevealed,Is.True);Assert.That(station.Memories.CaptureJson(),Is.EqualTo(memory));Assert.That(station.Journal.Store.Entries.Count,Is.EqualTo(2));Assert.That(station.Dialogue.Session.Messages.Count,Is.EqualTo(50));Assert.That(station.Dialogue.Session.Messages.Last().Text,Is.EqualTo("历史夹具59"));Assert.That(station.transform.position.x,Is.EqualTo(captured.Player.X).Within(.02));Assert.That(station.Player.Yaw,Is.EqualTo(215).Within(.01));Assert.That(station.Player.Pitch,Is.EqualTo(12).Within(.01));Assert.That(station.GetComponent<PlayerFlashlight>().IsOn,Is.True);Assert.That(station.Echo.CurrentMode,Is.EqualTo(IntentKind.Wait));Assert.That(station.Knowledge.IsReady,Is.True);Assert.That(station.GetComponent<PlayerInputReader>().UiBlocked,Is.False);var count=station.Memories.Store.Events.Count;yield return persistence.Load();Assert.That(persistence.LastSucceeded,Is.True,persistence.LastMessage);Assert.That(station.Memories.Store.Events.Count,Is.EqualTo(count));Assert.That(station.Journal.Store.Entries.Count,Is.EqualTo(2));
  }
  [UnityTest]public IEnumerator F03_C02_ActualMidVentilationLoadRestoresGatesAndContinuesRemainingTime()
  {
   yield return new EnterPlayMode();yield return Boot();var persistence=Store();var fresh=persistence.Capture();yield return UnlockCabin();yield return Interact("power_panel_01",new Vector3(-4.5f,-3.95f,26.8f));var power=station.GetComponent<StationPowerPanel>();foreach(var i in new[]{0,1,2})power.ToggleButton(i).onClick.Invoke();power.SubmitButton.onClick.Invoke();yield return Until(()=>power.Cycle.Elapsed>=1,4,"Power did not advance");Assert.That(power.Cycle.PassageReady,Is.False);var middle=persistence.Capture();Assert.That(persistence.CanRestore(middle,out var error),Is.True,error);yield return persistence.RestoreData(fresh);Assert.That(persistence.LastSucceeded,Is.True,persistence.LastMessage);Assert.That(power.Cycle.Powered,Is.False);yield return persistence.RestoreData(middle);Assert.That(persistence.LastSucceeded,Is.True,persistence.LastMessage);Assert.That(power.Cycle.Elapsed,Is.GreaterThanOrEqualTo(middle.Progress.VentElapsed));Assert.That(power.Cycle.Elapsed,Is.LessThan(middle.Progress.VentElapsed+.3f));Assert.That(power.Cycle.PassageReady,Is.False);Assert.That(station.Progress.Has("pz03"),Is.True);var gates=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<StationGate>()).ToArray();Assert.That(gates.Single(g=>g.name=="Vent_Isolation").IsOpen,Is.False);WorldTarget.Active.TryGet("cabin_door_01",out var door);Assert.That(door.GetComponent<StationGate>().IsOpen,Is.True);yield return Until(()=>power.Cycle.PassageReady,4,"Restored ventilation did not finish");Assert.That(gates.Single(g=>g.name=="Vent_Isolation").IsOpen,Is.True);var fog=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<LocalFogField>()).Single();Assert.That(fog.Recovery,Is.EqualTo(1));Assert.That(station.Memories.Store.Events.Count(e=>e.Id=="progress_pz03"),Is.EqualTo(1));
  }
  [UnityTest]public IEnumerator F03_C03_InvalidCandidateDoesNotChangePoseJournalMemoryHistoryOrFlags()
  {
   yield return new EnterPlayMode();yield return Boot();station.Player.enabled=false;var persistence=Store();var valid=persistence.Capture();var beforePosition=station.transform.position;var memory=station.Memories.CaptureJson();var dialogue=station.Dialogue.Session.Messages.ToArray();foreach(var mutate in new Action<StationSaveData>[]{s=>s.Progress.Journal=new[]{"unknown_record"},s=>s.Progress.Scans=new[]{"scan_mark_01"},s=>s.Player.X=20,s=>s.Progress.CoreOpen=true,s=>s.Elapsed=-1}){var bad=StationSaveJson.Decode(StationSaveJson.Encode(valid)).Data;mutate(bad);Assert.That(persistence.CanRestore(bad,out _),Is.False);yield return persistence.RestoreData(bad);Assert.That(persistence.LastSucceeded,Is.False);Assert.That(station.transform.position,Is.EqualTo(beforePosition));Assert.That(station.Memories.CaptureJson(),Is.EqualTo(memory));Assert.That(station.Journal.Store.Entries,Is.Empty);Assert.That(station.Dialogue.Session.Messages,Is.EqualTo(dialogue));Assert.That(station.Restoring,Is.False);Assert.That(persistence.Busy,Is.False);}
  }
  [UnityTest]public IEnumerator F03_C04_InjectedCommitFailureRollsBackWorldMemoryAndAll100VisibleMessages()
  {
   yield return new EnterPlayMode();yield return Boot();station.Player.enabled=false;var persistence=Store();for(var i=0;i<100;i++)station.Dialogue.Session.TryAdd(DialogueSpeaker.Player,"回滚历史"+i,false,out _);var oldPosition=station.transform.position;var oldMemory=station.Memories.CaptureJson();var oldHistory=station.Dialogue.Session.Messages.ToArray();var candidate=persistence.Capture();candidate.Player.Z=-30;persistence.BeforeCommitForTest=()=>throw new InvalidOperationException("controlled_commit_failure");yield return persistence.RestoreData(candidate);Assert.That(persistence.LastSucceeded,Is.False);Assert.That(persistence.LastMessage,Does.Contain("已恢复原状态"));Assert.That(station.transform.position,Is.EqualTo(oldPosition));Assert.That(station.Memories.CaptureJson(),Is.EqualTo(oldMemory));Assert.That(station.Dialogue.Session.Messages,Is.EqualTo(oldHistory));Assert.That(station.Dialogue.Session.Messages.Count,Is.EqualTo(100));Assert.That(persistence.Busy,Is.False);Assert.That(station.Restoring,Is.False);Assert.That(station.Player.enabled,Is.False);Assert.That(station.Echo.IsInitialized,Is.True);Assert.That(station.Knowledge.IsReady,Is.True);
  }
  [TearDown]public void CleanupFiles(){if(directory==null||!Directory.Exists(directory))return;var parent=Path.GetFullPath(Path.Combine("Library","EchoStation","S2WorldSaveTests"))+Path.DirectorySeparatorChar;Assert.That(Path.GetFullPath(directory).StartsWith(parent,StringComparison.OrdinalIgnoreCase),Is.True);if(TestContext.CurrentContext.Result.Outcome.Status!=NUnit.Framework.Interfaces.TestStatus.Failed)Directory.Delete(directory,true);}
 }
}
